import { assertReadableModel, resourceGdr, } from '@sanity/workflow-engine';
import { clientFor, resolveTokenOrFail } from "./client.js";
import { fail } from "./fail.js";
import { loadWorkflowConfig } from "./load-config.js";
import { deploymentsForTag, selectDeployment } from "./select-deployment.js";
import { resourceLabel } from "./ui.js";
export async function resolveContext(flags) {
    const config = await loadWorkflowConfig();
    const deployment = await selectDeployment(config, { name: flags.deployment, tag: flags.tag });
    return { deployment, client: clientFor(deployment.workflowResource, await resolveTokenOrFail()) };
}
function targetsFor(resources, token) {
    return resources.map((resource) => ({ resource, client: clientFor(resource, token) }));
}
export async function resolveReadTargets(flags) {
    const config = await loadWorkflowConfig();
    const resources = resolveReadResources(config, flags.tag);
    return targetsFor(resources, await resolveTokenOrFail());
}
export function dedupeResources(resources) {
    return [...new Map(resources.map((resource) => [resourceGdr(resource), resource])).values()];
}
export function resolveReadResources(config, tag) {
    if (tag !== undefined) {
        return dedupeResources(deploymentsForTag(config, tag).map((deployment) => deployment.workflowResource));
    }
    const resources = dedupeResources(config.deployments.map((d) => d.workflowResource));
    if (resources.length === 0) {
        fail('No deployments configured.');
    }
    return resources;
}
const LOCATE_TAG = 'instance.load';
export async function resolveInstanceContext(flags, instanceId) {
    const config = await loadWorkflowConfig();
    const token = await resolveTokenOrFail();
    const hit = await locateInstance({
        config,
        flags,
        instanceId,
        token,
        find: (targets) => findInstance({ targets, instanceId, requestTag: LOCATE_TAG }),
    });
    if (hit === undefined) {
        fail(`Workflow instance ${instanceId} not found`);
    }
    return {
        client: hit.client,
        scope: { tag: hit.instance.tag, workflowResource: hit.resource },
        instance: hit.instance,
    };
}
export async function resolveInstanceStamps(flags, instanceId) {
    const config = await loadWorkflowConfig();
    const token = await resolveTokenOrFail();
    const hit = await locateInstance({
        config,
        flags,
        instanceId,
        token,
        find: (targets) => findInstanceStamps({ targets, instanceId, requestTag: LOCATE_TAG }),
    });
    if (hit === undefined) {
        fail(`Workflow instance ${instanceId} not found`);
    }
    return { resource: hit.resource, stamps: hit.stamps };
}
async function locateInstance({ config, flags, instanceId, token, find, }) {
    const resources = await instanceCandidateResources(config, flags);
    const fanOut = () => find(targetsFor(resources, token));
    const explicit = flags.deployment !== undefined || flags.tag !== undefined;
    const hinted = explicit || resources.length <= 1
        ? []
        : hintedResources({ config, instanceId, candidates: resources });
    if (hinted.length === 0 || hinted.length === resources.length) {
        return fanOut();
    }
    const hit = await hintedProbe(() => find(targetsFor(hinted, token)));
    return hit ?? fanOut();
}
async function hintedProbe(probe) {
    try {
        return await probe();
    }
    catch {
        return undefined;
    }
}
async function instanceCandidateResources(config, { deployment, tag }) {
    if (deployment !== undefined) {
        return [(await selectDeployment(config, { name: deployment, tag: undefined })).workflowResource];
    }
    return resolveReadResources(config, tag);
}
function hintedResources({ config, instanceId, candidates, }) {
    const dot = instanceId.indexOf('.');
    if (dot <= 0) {
        return [];
    }
    const prefix = instanceId.slice(0, dot);
    const taggedGdrs = new Set(config.deployments
        .filter((deployment) => deployment.tag === prefix)
        .map((deployment) => resourceGdr(deployment.workflowResource)));
    return candidates.filter((resource) => taggedGdrs.has(resourceGdr(resource)));
}
export function soleHitOrFail(hits, subject) {
    const [sole, ...rest] = hits;
    if (rest.length > 0) {
        fail(`${subject} exists in several resources — pass --tag to choose one.`, hits.map((hit) => resourceLabel(hit.resource)).join('\n'));
    }
    return sole;
}
async function findAcrossTargets({ targets, subject, probe, }) {
    const probes = await Promise.allSettled(targets.map(probe));
    const hits = probes
        .filter((settled) => settled.status === 'fulfilled')
        .map((settled) => settled.value)
        .filter((hit) => hit !== undefined);
    const sole = soleHitOrFail(hits, subject);
    if (sole !== undefined) {
        return sole;
    }
    const failedProbe = probes.find((settled) => settled.status === 'rejected');
    if (failedProbe !== undefined) {
        throw failedProbe.reason;
    }
    return undefined;
}
export function findInstance({ targets, instanceId, requestTag, }) {
    return findAcrossTargets({
        targets,
        subject: `Instance ${instanceId}`,
        probe: async (target) => {
            const instance = await target.client.getDocument(instanceId, {
                tag: requestTag,
            });
            return instance === undefined
                ? undefined
                : { ...target, instance: assertReadableModel(instance) };
        },
    });
}
function findInstanceStamps({ targets, instanceId, requestTag, }) {
    return findAcrossTargets({
        targets,
        subject: `Instance ${instanceId}`,
        probe: async (target) => {
            const stamps = await target.client.fetch(`*[_id == $instanceId][0]{_type, tag, completedAt, abortedAt}`, { instanceId }, { perspective: 'raw', tag: requestTag });
            return stamps === null ? undefined : { ...target, stamps };
        },
    });
}
